import { mergeProps, splitProps } from '@benosjs/dom'
import type { JSX } from '@benosjs/dom'

export type BadgeTone = 'neutral' | 'brand' | 'success' | 'warning' | 'danger'

export type BadgeProps = Omit<JSX.IntrinsicElements['span'], 'class' | 'ref'> & {
  id?: string
  class?: string
  tone?: BadgeTone
  ref?: (element: HTMLSpanElement) => void
}

export function Badge(props: BadgeProps): JSX.Element {
  const merged = mergeProps({ tone: 'neutral' as const }, props)
  const [local, native] = splitProps(merged, ['tone', 'class', 'ref', 'children'] as const)
  const ref = (element: HTMLSpanElement) => local.ref?.(element)

  return (
    <span
      {...native}
      class={['benos-badge', 'benos-badge--' + local.tone, local.class].filter(Boolean).join(' ')}
      ref={ref}
    >
      {local.children}
    </span>
  )
}

.benos-badge {
  align-items: center;
  border: 1px solid currentColor;
  border-radius: var(--benos-radius-pill);
  display: inline-flex;
  font-size: var(--benos-text-xs);
  font-weight: 650;
  gap: var(--benos-space-1);
  line-height: 1.4;
  padding-block: 0.15em;
  padding-inline: var(--benos-space-2);
}

.benos-badge--neutral {
  color: var(--benos-color-text-muted);
}

.benos-badge--brand {
  color: var(--benos-color-brand);
}

.benos-badge--success {
  color: var(--benos-color-success);
}

.benos-badge--warning {
  color: var(--benos-color-warning);
}

.benos-badge--danger {
  color: var(--benos-color-danger);
}
